import React, { createContext, useContext, useEffect, useState } from 'react';

export interface DownloadItem {
  id: string;
  mediaId: string;
  mediaType: 'movie' | 'tv';
  title: string;
  poster?: string;
  quality: string;
  fileSize: string;
  estimatedTime: string;
  status: 'pending' | 'downloading' | 'paused' | 'completed' | 'failed';
  progress: number;
  downloadSpeed?: string;
  eta?: string;
  createdAt: string;
  updatedAt: string;
}

import Colors from '@/constants/Colors';
import { useDownloads, type DownloadItem } from '@repo/context';
import { Ionicons } from '@expo/vector-icons';

const activeDownloads = downloads.filter(
  (d: DownloadItem) => d.status === 'downloading' || d.status === 'pending',
);
const completedDownloads = downloads.filter((d: DownloadItem) => d.status === 'completed');
const pausedDownloads = downloads.filter((d: DownloadItem) => d.status === 'paused');
const failedDownloads = downloads.filter((d: DownloadItem) => d.status === 'failed');

